 public static readonly FictionBook[] Books=[
  new("Son Işığın Bekçisi","Üç bölümlük özgün kurmaca: bir fenerin ışığını kimin taşıdığı üzerine.",[
   "Limanın ışığı her gece tam dokuzda yanardı. Ada bunun otomatik bir düzenek olduğunu düşünürdü; düğmesi bile olmayan taş kulübeye bu yüzden hiç girmemişti. Bir akşam ışık yanmadı. Balıkçılar teknelerini yavaşlatırken kulübenin kapısında bir zarf buldu. Zarfın içinde tek cümle vardı: 'Işığı yakmak için kaybolmuş birine yol tarif et.' Ada çevresine baktı. Sokaktaki herkes kendi evine gidiyordu. Yalnızca iskelede bekleyen çocuk elindeki kâğıdı ters tutuyordu.",
   "Çocuk bir adres aramıyordu. Kâğıtta annesinin gençken anlattığı bir limanın resmi vardı; kule yuvarlak, çatılar mavi, sokak lambaları kısaydı. Şimdiki limanda bunların hiçbiri kalmamıştı. Ada eski fotoğrafları düşündü ve çocuğu taş basamaklara götürdü. 'Belki aradığın yer burasıdır ama aynı zamanda başka bir zamandır' dedi. Çocuk resmi duvara yaslayınca eski kuleyle yeni kulenin çizgileri birleşti. Limanın ışığı bir anlığına parladı, sonra yeniden söndü.",
   "Ada kulübeye dönüp masanın üzerindeki defteri açtı. Her sayfada bir yol tarifi vardı: kimi bir eve, kimi kaybolan bir alışkanlığa, kimi de artık sorulmayan bir soruya çıkıyordu. Son sayfa boştu. Ada kendi tarifini yazdı: 'Birini dinlemeye vaktin olmadığı anda dur. Işığın düğmesi belki de odur.' Çocuk yanına gelip resmin arkasını çevirdi. Aynı cümle daha eski bir el yazısıyla orada da duruyordu. Bu kez fener yandığında kimse düğmeyi aramadı."
  ]),
  new("Eksik Sandalyenin Haritası","Üç bölümlük özgün kurmaca: bir toplantıda ayrılan yerin peşinden.",[
   "Atölyedeki masanın etrafında yedi sandalye vardı ama davet edilen kişi sayısı altıydı. Deniz fazlalığı depoya taşımak istediğinde sandalyenin altından katlanmış bir kroki düştü. Krokide atölyenin içi çizilmiş, kapıyla pencere arasındaki boşluğa 'henüz gelmeyen' yazılmıştı. Diğerleri bunun önceki kiracıdan kaldığını söyledi. Akşam herkes yerleşince boş sandalye kendi kendine pencereye doğru birkaç santim kaydı. Kimse yüksek sesle bunu fark ettiğini söylemedi.",
   "Sonraki hafta kapıda yeni biri belirdi. Adını değil, elindeki yarım işi gösterdi: ortasında boşluk olan bir masa modeli. 'Burada eksik parçaları konuşuyormuşsunuz' dedi. Deniz sandalyeyi uzattı. Yeni gelen oturunca krokideki çizgiler değişti; bu kez boşluk masanın ortasındaydı. Atölye boyunca herkes bitirdiği şeyleri anlatmıştı. İlk kez biri nerede durduğunu anlattı. Masanın ortasındaki boşluk, kimsenin elini koymak istemediği bir soruya benziyordu.",
   "Deniz krokiyi yeni bir kâğıda kopyaladı ve boş sandalyenin yerini işaretlemedi. Onun yerine her katılımcıya küçük bir kalem verdi. Buluşma sonunda herkes bir boşluk çizmişti: bazısı dinlenmek için, bazısı başka birinin fikrini beklemek için, bazısı yanlış yapabilmek için. Yedinci sandalye yine boş kaldı. Fakat artık fazlalık sayılmıyordu. Atölyenin kapısına asılan haritada odalar kadar, henüz dolması gerekmeyen yerler de görünüyordu."
  ]),
  new("Dakika Bahçesi","Üç bölümlük özgün kurmaca: saklanan zaman ve paylaşılan dikkat.",[
   "Bahçıvan saksılara çiçek adı yazmıyordu. Birinde 'acele etmeden verilen yanıt', diğerinde 'yarım bırakılan yürüyüş' yazıyordu. Ece bunların şiir olduğunu sandı. Bahçıvan bir saksıyı kaldırıp kulağına yaklaştırdı. İçinden iki kişinin aynı anda konuşmayı bırakıp birbirini beklediği kadar kısa bir sessizlik geldi. 'Bunlar dakika' dedi. 'Saklananlar değil, yaşanmasına yer açılanlar.' Bahçenin en arkasındaki saksı ise tamamen boştu.",
   "Şehirde bütün saatler aynı gün durduğunda insanlar bahçeye geldi. Herkes işe, eve veya bir buluşmaya yetişecek kadar dakika istiyordu. Bahçıvan kimseye saksı vermedi. Ece bunun haksızlık olduğunu düşündü. Sonra boş saksının üzerinde küçük bir yazı gördü: 'Birlikte ayıracağınız zaman.' İnsanlar ilk kez kuyrukta birbirine neye yetişmeye çalıştığını sormaya başladı. Bazı buluşmaların ertelenebildiği, bazı telefonların hemen açılması gerektiği o konuşmada anlaşıldı.",
   "Saatler yeniden çalıştığında kuyruk dağılmadı. İnsanlar artık aynı şeyi beklemiyordu ama birbirinin zamanına dikkat ediyordu. Ece boş saksıya toprak koydu. İçine bir tohum yerine ertesi gün için ayırdığı küçük bir boşluğu bıraktı: on dakika boyunca hiçbir şeyi bitirmeye çalışmayacaktı. Bahçıvan saksıya etiket yazmadı. 'Bunun ne olacağını birlikte görürüz' dedi. O gün bahçede ilk kez saat değil, takvim çiçek açtı."
  ]),
  new("Kopyalanmayan Ses","Üç bölümlük özgün kurmaca: bir kaydın eksik bıraktığı yakınlık.",[
   "Radyo tamircisi bütün sesleri kopyalayabilirdi. Çatlayan bir kapı, eski bir tramvay, çok uzaktaki bir alkış. Ama her denemede aynı ses kayıttan siliniyordu: birinin 'buradayım' deyişi. Kayıtta sözcükler kalıyor, dinleyen ise söylenen şeyi duymadığını hissediyordu. Aras bunu cihazın arızası sanıp masanın altındaki kabloları değiştirdi. Tamirci ona yeni bir kaset verdi. Kasetin üzerinde 'boşken dene' yazıyordu.",
   "Aras kaseti sessiz bir odaya götürdü ve kaydı açtı. Hiçbir şey duymadı. Tam kapatacakken yan odadan birinin sandalyeyi çektiğini işitti. O kişi içeri gelip konuşmadan oturdu. Aras tekrar dinlediğinde boş kasetin içinde odayla aynı büyüklükte bir sessizlik vardı. 'Bu bir ses değil' dedi. Yanındaki kişi başını salladı. Kasetin taşıyamadığı şeyin yalnızca sözcük olmadığını, birinin gerçekten orada bulunmasını da içerdiğini anladı.",
   "Tamirci kaseti geri almadı. Aras onu bir hatırlatma olarak sakladı: her şeyi kayıt altına almak, her şeyi birine ulaştırmak değildi. Bir gün kendi dükkânını açtığında vitrine en pahalı cihazı değil, boş bir sandalye koydu. Gelenler önce ondan ne istediklerini anlatıyordu. Aras bazen tamir ediyordu, bazen yalnızca dinliyordu. Kaset hâlâ sessizdi. Ama artık bu sessizlik eksiklik gibi gelmiyordu."
  ])
 ];
 public static readonly LessonDraft[] Lessons=[
  new("Bir savı somutlaştırmak","Bir iddiayı tartışabilmek için kapsamını belirtmek gerekir. 'Bu oyun eğlenceli' sözü kişisel bir deneyimi anlatır. 'Bu oyunda ilk turda herkes bir hamle yapabiliyor' sözü ise gözlenebilecek belirli bir davranışı tanımlar. Bu ayrım, kişisel görüşü küçümsemek için değil, hangi bilginin nasıl değerlendirileceğini anlamak için kullanılır.","Aşağıdaki cümlelerden hangisi doğrudan gözlenebilir bir davranış tanımlar?",["Bu en iyi oyundur.","İlk turda her katılımcı bir hamle yapar.","Bu oyun herkesi mutlu eder.","Bu oyun diğerlerinden daha değerlidir."],1,"İkinci seçenek, belirli bir turda katılımcıların ne yaptığına dair gözlenebilir bir davranış belirtir. Diğerleri geniş veya kişisel değerlendirmelerdir."),
  new("Küçük bir işlem sırası","Bir görevi devralacak kişiye yalnız hedefi söylemek bazen yeterli olmaz. Girdi, yapılacak işlem ve beklenen çıktı birlikte belirtilirse görev daha kolay anlaşılır. Örneğin: 'Üç başlığı al, tarih sırasına koy, tek bir liste döndür.' Bu cümlede hangi verinin kullanıldığı ve işin ne zaman bittiği açıktır.","'Üç başlığı al, tarih sırasına koy, tek bir liste döndür' görevinde beklenen çıktı hangisidir?",["Üç yeni başlık yazmak","Başlıkların rengini değiştirmek","Tarih sırasındaki tek liste","Görev sahibine yeni bir soru sormak"],2,"Beklenen çıktı tarih sırasına konmuş tek listedir. Görevin girdi ve işlem adımları bu çıktıyı üretmeye yöneliktir."),
  new("Basit örüntüyü okumak","Bir örüntüyü açıklarken görülen sayılarla varsayılan kuralı ayırmak gerekir. '2, 4, 6, 8' dizisi iki ekleme kuralıyla devam ettirilebilir. Eğer görev açıkça her adımda iki eklendiğini söylüyorsa sonraki sayı bu kurala göre hesaplanır. Kuralların açık yazılması, farklı geçerli yorumların karışmasını azaltır.","Her adımda 2 eklenen 2, 4, 6, 8 dizisinin sonraki sayısı nedir?",["9","10","12","16"],1,"Açıkça verilen kurala göre 8'e 2 eklenir ve 10 elde edilir."
  )
 ];
